package cli

import (
	"path/filepath"
	"strings"
	"testing"
)

func TestDoctorInstallPathReport(t *testing.T) {
	t.Parallel()
	home := "/Users/test"
	localBin := filepath.Join(home, ".local", "bin")
	goBin := filepath.Join(home, "go", "bin")

	t.Run("local bin off PATH", func(t *testing.T) {
		t.Parallel()
		got := doctorInstallPathReport(filepath.Join(localBin, "wanderlog-pp-cli"), "/usr/bin:/bin", home, "")
		path, _ := got["path"].(string)
		if !strings.HasPrefix(path, "WARN") {
			t.Fatalf("path = %q, want WARN", path)
		}
		hint, _ := got["path_hint"].(string)
		if !strings.Contains(hint, `export PATH="`+localBin+`:$PATH"`) {
			t.Fatalf("hint = %q, want export PATH for %s", hint, localBin)
		}
		if !strings.Contains(hint, "wanderlog-pp-cli") || !strings.Contains(hint, "not wanderlog") {
			t.Fatalf("hint = %q, want wanderlog-pp-cli not wanderlog", hint)
		}
		if got["binary"] != "wanderlog-pp-cli" {
			t.Fatalf("binary = %v", got["binary"])
		}
	})

	t.Run("gopath bin off PATH", func(t *testing.T) {
		t.Parallel()
		got := doctorInstallPathReport(filepath.Join("/opt/go", "bin", "wanderlog-pp-cli"), "/usr/bin", home, "/opt/go")
		path, _ := got["path"].(string)
		if !strings.HasPrefix(path, "WARN") {
			t.Fatalf("path = %q, want WARN", path)
		}
		hint, _ := got["path_hint"].(string)
		if !strings.Contains(hint, "/opt/go/bin") {
			t.Fatalf("hint = %q, want GOPATH/bin", hint)
		}
	})

	t.Run("default GOPATH when empty", func(t *testing.T) {
		t.Parallel()
		got := doctorInstallPathReport(filepath.Join(goBin, "wanderlog-pp-cli"), "/usr/bin", home, "")
		path, _ := got["path"].(string)
		if !strings.HasPrefix(path, "WARN") {
			t.Fatalf("empty GOPATH should treat %s as install dir, path=%q", goBin, path)
		}
	})

	t.Run("local bin on PATH", func(t *testing.T) {
		t.Parallel()
		got := doctorInstallPathReport(filepath.Join(localBin, "wanderlog-pp-cli"), localBin+":/usr/bin", home, "")
		if got["path"] != "ok" {
			t.Fatalf("path = %v, want ok", got["path"])
		}
		if _, ok := got["path_hint"]; ok {
			t.Fatalf("unexpected path_hint: %v", got["path_hint"])
		}
	})

	t.Run("tilde PATH entry", func(t *testing.T) {
		t.Parallel()
		got := doctorInstallPathReport(filepath.Join(localBin, "wanderlog-pp-cli"), "~/.local/bin:/usr/bin", home, "")
		if got["path"] != "ok" {
			t.Fatalf("tilde PATH should match, path=%v", got["path"])
		}
	})

	t.Run("unwatched dir", func(t *testing.T) {
		t.Parallel()
		got := doctorInstallPathReport("/usr/local/bin/wanderlog-pp-cli", "/usr/bin", home, "")
		if got["path"] != "ok" {
			t.Fatalf("unwatched dir should not warn, path=%v", got["path"])
		}
		if got["binary_note"] != "the binary is wanderlog-pp-cli, not wanderlog" {
			t.Fatalf("binary_note = %v", got["binary_note"])
		}
	})
}
